148	// registryGETContext is registryGET bound to ctx.
149	func registryGETContext(ctx context.Context, rawURL, username, password, token string) (body []byte, link, usedToken string, err error) {
150		resp, token, err := registryDoContext(ctx, http.MethodGet, rawURL, "", username, password, token)
151		if err != nil {
152			return nil, "", token, err
153		}
154		defer func() { _ = resp.Body.Close() }()
155		if resp.StatusCode != http.StatusOK {
156			return nil, "", token, &StatusError{Code: resp.StatusCode, Source: SourceRegistry}
157		}
158		body, err = io.ReadAll(io.LimitReader(resp.Body, maxTagResponse))
159		return body, resp.Header.Get("Link"), token, err
160	}
161	
162	// registryDo sends one request, answering a Bearer challenge once. The caller
163	// closes the response body and reads the status.
164	func registryDo(method, rawURL, accept, username, password, token string) (*http.Response, string, error) {
165		return registryDoContext(context.Background(), method, rawURL, accept, username, password, token)
166	}
167	
168	// registryDoContext is registryDo bound to ctx.
169	func registryDoContext(ctx context.Context, method, rawURL, accept, username, password, token string) (*http.Response, string, error) {
170		resp, err := doRequestContext(ctx, method, rawURL, accept, username, password, token)
171		if err != nil {
172			return nil, token, err
173		}
174		if resp.StatusCode != http.StatusUnauthorized {
175			return resp, token, nil
176		}
177		challenge := resp.Header.Get("Www-Authenticate")
178		_ = resp.Body.Close()
179		if !strings.HasPrefix(challenge, "Bearer ") {
180			return nil, token, &StatusError{Code: http.StatusUnauthorized, Source: SourceRegistry, Challenge: challenge, unexpectedChallenge: true}
181		}
182		token, err = exchangeBearerTokenContext(ctx, challenge[7:], username, password)
183		if err != nil {
184			return nil, "", err
185		}
186		if resp, err = doRequestContext(ctx, method, rawURL, accept, "", "", token); err != nil {
187			return nil, token, fmt.Errorf("%s (retry) %s: %w", method, rawURL, err)
188		}
189		return resp, token, nil
190	}
191	
192	// doRequest sends one request: a bearer token when there is one, Basic auth
193	// when there are credentials and no token.
194	func doRequest(method, rawURL, accept, username, password, token string) (*http.Response, error) {
195		return doRequestContext(context.Background(), method, rawURL, accept, username, password, token)
196	}
197	
198	// doRequestContext is doRequest bound to ctx; a context already done sends
199	// nothing.
200	func doRequestContext(ctx context.Context, method, rawURL, accept, username, password, token string) (*http.Response, error) {
201		req, err := http.NewRequestWithContext(ctx, method, rawURL, nil)
202		if err != nil {
203			return nil, fmt.Errorf("build request: %w", err)
204		}
205		if accept != "" {
206			req.Header.Set("Accept", accept)
207		}
208		switch {
209		case token != "":
210			req.Header.Set("Authorization", "Bearer "+token)
211		case username != "" && password != "":
212			req.SetBasicAuth(username, password)
213		}
214		resp, err := registryHTTPClient.Do(req)
215		if err != nil {
216			return nil, fmt.Errorf("%s %s: %w", method, rawURL, err)
217		}
218		return resp, nil
219	}
220	
221	// manifestAccept lists every manifest kind a tag can point to. A multi-platform
222	// tag is an index (or a Docker manifest list), and its digest is the one `docker
223	// pull` records in RepoDigests; asking for a single-platform manifest only
224	// would make the registry convert or refuse, and the digests would not match.
225	var manifestAccept = strings.Join([]string{
226		"application/vnd.oci.image.index.v1+json",
227		"application/vnd.docker.distribution.manifest.list.v2+json",
228		"application/vnd.oci.image.manifest.v1+json",
229		"application/vnd.docker.distribution.manifest.v2+json",
230	}, ", ")
231	
232	// ManifestDigest returns the digest a tag currently points to, from the
233	// registry's Docker-Content-Digest header.
234	//
235	// It is a HEAD request: Docker Hub does not count a HEAD against the pull rate
236	// limit, and nothing but the header is needed.
237	func ManifestDigest(apiURL, repo, tag, username, password string) (string, error) {
238		rawURL := fmt.Sprintf("%s/v2/%s/manifests/%s", strings.TrimSuffix(apiURL, "/"), repo, url.PathEscape(tag))
239		resp, _, err := registryDo(http.MethodHead, rawURL, manifestAccept, username, password, "")
240		if err != nil {
241			return "", err
242		}
243		_ = resp.Body.Close()
244		if resp.StatusCode != http.StatusOK {
245			return "", fmt.Errorf("registry returned %d for %s:%s", resp.StatusCode, repo, tag)
246		}
247		digest := resp.Header.Get("Docker-Content-Digest")
248		if digest == "" {
249			return "", fmt.Errorf("registry gave no digest for %s:%s", repo, tag)
250		}
251		return digest, nil
252	}
253	
254	// RegistryAPIBase is the v2 API root of a registry named in an image reference:
255	// Docker Hub has its own host, a local registry is reached over plain HTTP, and
256	// everything else over HTTPS. An empty registry is Docker Hub.
257	func RegistryAPIBase(registry string) string {
258		switch {
259		case registry == "":
260			return "https://registry-1.docker.io"
261		case strings.HasPrefix(registry, "localhost") || strings.HasPrefix(registry, "127.0.0.1"):
262			return "http://" + registry
263		}
264		return "https://" + registry
265	}
266	
267	// resolveNext is the URL a Link header's rel="next" points to, resolved against
268	// the page it came with — registries send it as a path — or "" when there is
269	// none. A next link that leads back to the page just read ends the walk rather
270	// than looping on it.
271	func resolveNext(current, link string) string {
272		for _, part := range strings.Split(link, ",") {
273			target, rel, ok := strings.Cut(strings.TrimSpace(part), ";")
274			if !ok || !strings.Contains(rel, `rel="next"`) {
275				continue
276			}
277			target = strings.Trim(strings.TrimSpace(target), "<>")
278			base, err := url.Parse(current)
279			if err != nil {
280				return ""
281			}
282			ref, err := url.Parse(target)
283			if err != nil {
284				return ""
285			}
286			if next := base.ResolveReference(ref).String(); next != current {
287				return next
288			}
289		}
290		return ""
291	}
