298	// exchangeBearerTokenContext is exchangeBearerToken bound to ctx.
299	func exchangeBearerTokenContext(ctx context.Context, challenge, username, password string) (string, error) {
300		params := parseBearerChallenge(challenge)
301		realm, ok := params["realm"]
302		if !ok {
303			return "", fmt.Errorf("bearer challenge missing realm")
304		}
305		u, err := url.Parse(realm)
306		if err != nil {
307			return "", fmt.Errorf("parse realm %q: %w", realm, err)
308		}
309		q := u.Query()
310		if s, ok := params["service"]; ok {
311			q.Set("service", s)
312		}
313		if s, ok := params["scope"]; ok {
314			q.Set("scope", s)
315		}
316		u.RawQuery = q.Encode()
317	
318		req, err := http.NewRequestWithContext(ctx, http.MethodGet, u.String(), nil)
319		if err != nil {
320			return "", fmt.Errorf("build token request: %w", err)
321		}
322		if username != "" && password != "" {
323			req.SetBasicAuth(username, password)
324		}
325		resp, err := registryHTTPClient.Do(req)
326		if err != nil {
327			return "", fmt.Errorf("fetch token: %w", err)
328		}
329		defer func() { _ = resp.Body.Close() }()
330		if resp.StatusCode != http.StatusOK {
331			return "", &StatusError{Code: resp.StatusCode, Source: SourceToken}
332		}
