13	
14	// registryHTTPClient is swapped by tests that must reach a stand-in for a
15	// registry by another address.
16	var registryHTTPClient = &http.Client{
17		Timeout:       15 * time.Second,
18		CheckRedirect: refuseOffOriginRedirect,
19	}
20	
21	// maxRedirects is net/http's default limit, kept now that CheckRedirect is set.
22	const maxRedirects = 10
23	
24	// refuseOffOriginRedirect keeps credentials on the origin they were meant for.
25	// It compares with the initial request (via[0]), not only the previous hop, so
26	// a chain that leaves the origin and comes back is refused too. The redirect is
27	// refused rather than followed without Authorization: a registry that moves
28	// content to another host is misconfigured for this client, and an explicit
29	// error is safer than a silent anonymous retry.
30	func refuseOffOriginRedirect(req *http.Request, via []*http.Request) error {
31		if len(via) >= maxRedirects {
32			return fmt.Errorf("stopped after %d redirects", maxRedirects)
33		}
34		if !sameOrigin(via[0].URL.String(), req.URL.String()) {
35			return fmt.Errorf("refusing redirect to another origin (%s)", req.URL.Host)
36		}
37		return nil
38	}
39	
40	const (
41		// maxTagPages bounds how many pages of a tag list are followed. A registry
42		// that pages (`?n=`, `Link: rel="next"`) answers a page at a time, and one
43		// that keeps answering "next" must not hold a caller forever.
44		maxTagPages = 100
45		// maxTagResponse bounds one page. Docker Hub answers a whole list in one
46		// response when no page size is given — measured at 9 125 tags for
47		// library/node (§3.2) — so the bound is generous, but it is a bound.
48		maxTagResponse = 32 << 20
49		// maxTokenResponse bounds a Bearer token endpoint's answer; a token is a
50		// few KiB, so a larger body is an error, not a silent cut.
51		maxTokenResponse = 1 << 20
52	)
53	
54	// StatusSource says which endpoint answered with a non-success status.
55	type StatusSource int
56	
57	const (
58		// SourceRegistry is the registry's v2 API.
59		SourceRegistry StatusSource = iota
60		// SourceToken is the Bearer token endpoint.
61		SourceToken
62	)
63	
64	// StatusError is a registry or token endpoint answering with a non-success
65	// status. Failures that are not a status (unreadable body, missing realm, no
66	// token field) are plain errors.
67	type StatusError struct {
68		Code   int
69		Source StatusSource
70		// Challenge is the Www-Authenticate header of a 401 whose challenge is not
71		// Bearer; empty otherwise.
72		Challenge string
73		// unexpectedChallenge tells that 401 apart from a 401 answered after a
74		// token exchange, so Error() keeps both historical messages.
75		unexpectedChallenge bool
76	}
77	
78	// Error returns the message the plain errors carried before the type existed.
79	func (e *StatusError) Error() string {
80		switch {
81		case e.Source == SourceToken:
82			return fmt.Sprintf("token endpoint returned %d", e.Code)
83		case e.unexpectedChallenge:
84			return fmt.Sprintf("unexpected auth challenge: %s", e.Challenge)
85		}
86		return fmt.Sprintf("registry returned %d", e.Code)
87	}
88	
89	// ListRegistryTags lists the tags of a repository through the registry's v2 API.
90	//
91	// apiURL is the API base (see the browser's registryAPIURL). Credentials, when
92	// given, go as Basic auth and, on a 401 that names a Bearer realm, to that
93	// realm's token endpoint — the flow Docker Hub and most hosted registries use.
94	// The token is kept for the following pages.
95	//
96	// The list is followed across pages: whatever a registry caps a response at,
97	// and Docker Hub does not, a repository with more tags than one page holds is
98	// returned whole. This is the one tag lister that speaks the Bearer flow; the
99	// template client's ListTags (Client.ListTags) reads a registry the user
100	// configured for templates and only ever sends Basic auth.
101	func ListRegistryTags(apiURL, repo, username, password string) ([]string, error) {
102		return ListRegistryTagsContext(context.Background(), apiURL, repo, username, password)
103	}
104	
105	// ListRegistryTagsContext is ListRegistryTags bound to ctx: a cancelled or
106	// expired context stops the walk, including a request in flight, and the
107	// returned error wraps the context's error. A context already done sends
108	// nothing. registryHTTPClient's own timeout still applies per request; when
109	// both expire, whichever comes first ends the request, and either way the
110	// error satisfies errors.Is(err, context.DeadlineExceeded).
111	func ListRegistryTagsContext(ctx context.Context, apiURL, repo, username, password string) ([]string, error) {
112		next := fmt.Sprintf("%s/v2/%s/tags/list", strings.TrimSuffix(apiURL, "/"), repo)
113		var (
114			tags  []string
115			token string
116		)
117		for page := 0; next != ""; page++ {
118			if page == maxTagPages {
119				return nil, fmt.Errorf("tag list of %s is longer than %d pages", repo, maxTagPages)
120			}
121			body, link, usedToken, err := registryGETContext(ctx, next, username, password, token)
122			if err != nil {
123				return nil, err
124			}
125			token = usedToken
126			var result struct {
127				Tags []string `json:"tags"`
128			}
129			if err := json.Unmarshal(body, &result); err != nil {
130				return nil, fmt.Errorf("decode tags response: %w", err)
131			}
132			tags = append(tags, result.Tags...)
133			current := next
134			if next = resolveNext(current, link); next != "" && !sameOrigin(current, next) {
135				// Never send credentials to another origin; keep what was read.
136				break
137			}
138		}
139		return tags, nil
140	}
141	
142	// registryGET performs a GET, answering a Bearer challenge once. It returns the
143	// body, the Link header, and the token to send on the following requests.
144	func registryGET(rawURL, username, password, token string) (body []byte, link, usedToken string, err error) {
145		return registryGETContext(context.Background(), rawURL, username, password, token)
146	}
147	
148	// registryGETContext is registryGET bound to ctx.
149	func registryGETContext(ctx context.Context, rawURL, username, password, token string) (body []byte, link, usedToken string, err error) {
150		resp, token, err := registryDoContext(ctx, http.MethodGet, rawURL, "", username, password, token)
151		if err != nil {
152			return nil, "", token, err
153		}
154		defer func() { _ = resp.Body.Close() }()
155		if resp.StatusCode != http.StatusOK {
156			return nil, "", token, &StatusError{Code: resp.StatusCode, Source: SourceRegistry}
157		}
158		body, err = io.ReadAll(io.LimitReader(resp.Body, maxTagResponse))
