162	// registryDo sends one request, answering a Bearer challenge once. The caller
163	// closes the response body and reads the status.
164	func registryDo(method, rawURL, accept, username, password, token string) (*http.Response, string, error) {
165		return registryDoContext(context.Background(), method, rawURL, accept, username, password, token)
166	}
