192	// doRequest sends one request: a bearer token when there is one, Basic auth
193	// when there are credentials and no token.
194	func doRequest(method, rawURL, accept, username, password, token string) (*http.Response, error) {
195		return doRequestContext(context.Background(), method, rawURL, accept, username, password, token)
196	}
197	
198	// doRequestContext is doRequest bound to ctx; a context already done sends
199	// nothing.
200	func doRequestContext(ctx context.Context, method, rawURL, accept, username, password, token string) (*http.Response, error) {
201		req, err := http.NewRequestWithContext(ctx, method, rawURL, nil)
202		if err != nil {
203			return nil, fmt.Errorf("build request: %w", err)
204		}
205		if accept != "" {
206			req.Header.Set("Accept", accept)
207		}
208		switch {
209		case token != "":
210			req.Header.Set("Authorization", "Bearer "+token)
211		case username != "" && password != "":
212			req.SetBasicAuth(username, password)
213		}
214		resp, err := registryHTTPClient.Do(req)
215		if err != nil {
216			return nil, fmt.Errorf("%s %s: %w", method, rawURL, err)
217		}
218		return resp, nil
219	}
