221	// manifestAccept lists every manifest kind a tag can point to. A multi-platform
222	// tag is an index (or a Docker manifest list), and its digest is the one `docker
223	// pull` records in RepoDigests; asking for a single-platform manifest only
224	// would make the registry convert or refuse, and the digests would not match.
225	var manifestAccept = strings.Join([]string{
226		"application/vnd.oci.image.index.v1+json",
227		"application/vnd.docker.distribution.manifest.list.v2+json",
228		"application/vnd.oci.image.manifest.v1+json",
229		"application/vnd.docker.distribution.manifest.v2+json",
230	}, ", ")
231	
232	// ManifestDigest returns the digest a tag currently points to, from the
233	// registry's Docker-Content-Digest header.
234	//
235	// It is a HEAD request: Docker Hub does not count a HEAD against the pull rate
236	// limit, and nothing but the header is needed.
237	func ManifestDigest(apiURL, repo, tag, username, password string) (string, error) {
238		rawURL := fmt.Sprintf("%s/v2/%s/manifests/%s", strings.TrimSuffix(apiURL, "/"), repo, url.PathEscape(tag))
239		resp, _, err := registryDo(http.MethodHead, rawURL, manifestAccept, username, password, "")
240		if err != nil {
241			return "", err
242		}
243		_ = resp.Body.Close()
244		if resp.StatusCode != http.StatusOK {
245			return "", fmt.Errorf("registry returned %d for %s:%s", resp.StatusCode, repo, tag)
246		}
247		digest := resp.Header.Get("Docker-Content-Digest")
248		if digest == "" {
249			return "", fmt.Errorf("registry gave no digest for %s:%s", repo, tag)
250		}
251		return digest, nil
252	}
253	
254	// RegistryAPIBase is the v2 API root of a registry named in an image reference:
255	// Docker Hub has its own host, a local registry is reached over plain HTTP, and
256	// everything else over HTTPS. An empty registry is Docker Hub.
257	func RegistryAPIBase(registry string) string {
258		switch {
259		case registry == "":
260			return "https://registry-1.docker.io"
261		case strings.HasPrefix(registry, "localhost") || strings.HasPrefix(registry, "127.0.0.1"):
262			return "http://" + registry
263		}
264		return "https://" + registry
265	}
