153			return head + strings.Repeat("a", total-len(head)-len(tail)) + tail
154		}
155		atBound, overBound := pad(bound), pad(bound+1)
156		if len(atBound) != bound || len(overBound) != bound+1 {
157			t.Fatalf("fixture sizes %d, %d", len(atBound), len(overBound))
158		}
